ICONS = ['AppIcon.png']

def write_files():
    for rel, b64 in FILES.items():
        if isinstance(b64, tuple): b64 = ''.join(b64)
        data = base64.b64decode(b64)
        dst = os.path.join(ROOT, rel)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(dst, 'wb') as f: f.write(data)
    print(f'[setup] Wrote {len(FILES)} files')

def collect_sources():
    swift, headers = [], []
    src = os.path.join(ROOT, 'Sources')
    for dirpath, _, filenames in os.walk(src):
        for f in filenames:
            p = os.path.join(dirpath, f)
            if f.endswith('.swift') or f.endswith('.m') or f.endswith('.c'): swift.append(p)
            elif f.endswith('.h'): headers.append(p)
    return sorted(swift), sorted(headers)


def gen_xcodeproj():
    PROJECT_ID    = uid("PROJECT")
    NATIVE_TARGET = uid("NATIVE_TARGET")
    BCL_PROJECT   = uid("BCL_PROJECT")
    BCL_TARGET    = uid("BCL_TARGET")
    SOURCES_PHASE    = uid("SOURCES_PHASE")
    FRAMEWORKS_PHASE = uid("FRAMEWORKS_PHASE")
    RESOURCES_PHASE  = uid("RESOURCES_PHASE")
    MAIN_GROUP     = uid("MAIN_GROUP")
    SOURCES_GROUP  = uid("SOURCES_GROUP")
    PRODUCTS_GROUP = uid("PRODUCTS_GROUP")
    APP_REF   = uid("APP_PRODUCT_REF")
    PLIST_REF = uid("INFOPLIST_FILE")
    PLIST_BF  = uid("BUILDFILE_PLIST")

    swift_files, header_files = collect_sources()
    file_refs, build_files = {}, {}
    for path in swift_files + header_files:
        rel = os.path.relpath(path, ROOT)
        fid = uid("FILEREF_" + rel)
        bid = uid("BUILDFILE_" + rel)
        file_refs[rel] = (fid, path)
        build_files[rel] = bid

    icon_refs, icon_bfs = {}, {}
    for icon_name in ICONS:
        ipath = os.path.join(ROOT, icon_name)
        fid = uid("FILEREF_ICON_" + icon_name)
        bid = uid("BUILDFILE_ICON_" + icon_name)
        icon_refs[icon_name] = (fid, ipath)
        icon_bfs[icon_name] = bid

    L = []
    def W(s): L.append(s)

    W("// !$*UTF8*$!")
    W("{")
    W("\tarchiveVersion = 1;")
    W("\tclasses = {};")
    W("\tobjectVersion = 56;")
    W("\tobjects = {")
    W("")
    W("/* Begin PBXBuildFile section */")
    for rel, bid in build_files.items():
        fid = file_refs[rel][0]
        name = os.path.basename(rel)
        W(f"\t\t{bid} /* {name} in Sources */ = {{isa = PBXBuildFile; fileRef = {fid}; }};")
    for icon_name, bid in icon_bfs.items():
        fid = icon_refs[icon_name][0]
        W(f"\t\t{bid} /* {icon_name} in Resources */ = {{isa = PBXBuildFile; fileRef = {fid}; }};")
    W("/* End PBXBuildFile section */")
    W("")
    W("/* Begin PBXFileReference section */")
    W(f"\t\t{APP_REF} = {{isa = PBXFileReference; explicitFileType = wrapper.application; includeInIndex = 0; path = \"3105.app\"; sourceTree = BUILT_PRODUCTS_DIR; }};")
    plist_abs = os.path.join(ROOT, "Info.plist")
    W(f"\t\t{PLIST_REF} = {{isa = PBXFileReference; lastKnownFileType = text.plist.xml; path = \"{plist_abs}\"; sourceTree = \"<absolute>\"; name = \"Info.plist\"; }};")
    for rel, (fid, abspath) in file_refs.items():
        name = os.path.basename(rel)
        if rel.endswith(".swift"): ft = "sourcecode.swift"
        elif rel.endswith(".m"):   ft = "sourcecode.c.objc"
        elif rel.endswith(".c"):   ft = "sourcecode.c.c"
        else:                      ft = "sourcecode.c.h"
        W(f"\t\t{fid} = {{isa = PBXFileReference; lastKnownFileType = {ft}; path = \"{abspath}\"; sourceTree = \"<absolute>\"; name = \"{name}\"; }};")
    for icon_name, (fid, abspath) in icon_refs.items():
        W(f"\t\t{fid} = {{isa = PBXFileReference; lastKnownFileType = image.png; path = \"{abspath}\"; sourceTree = \"<absolute>\"; name = \"{icon_name}\"; }};")
    W("/* End PBXFileReference section */")
    W("")
    W("/* Begin PBXFrameworksBuildPhase section */")
    W(f"\t\t{FRAMEWORKS_PHASE} = {{isa = PBXFrameworksBuildPhase; buildActionMask = 2147483647; files = (); runOnlyForDeploymentPostprocessing = 0; }};")
    W("/* End PBXFrameworksBuildPhase section */")
    W("")
    W("/* Begin PBXGroup section */")
    W(f"\t\t{MAIN_GROUP} = {{isa = PBXGroup; children = ({SOURCES_GROUP},{PLIST_REF},{PRODUCTS_GROUP},); sourceTree = \"<group>\"; }};")
    src_children = "".join(f"\t\t\t{fid} /* {os.path.basename(rel)} */,\n" for rel,(fid,_) in file_refs.items())
    W(f"\t\t{SOURCES_GROUP} = {{isa = PBXGroup; children = (\n{src_children}\t\t); name = Sources; sourceTree = \"<group>\"; }};")
    W(f"\t\t{PRODUCTS_GROUP} = {{isa = PBXGroup; children = ({APP_REF},); name = Products; sourceTree = \"<group>\"; }};")
    W("/* End PBXGroup section */")
    W("")
    W("/* Begin PBXNativeTarget section */")
    W(f"\t\t{NATIVE_TARGET} = {{isa = PBXNativeTarget; buildConfigurationList = {BCL_TARGET}; buildPhases = ({SOURCES_PHASE},{FRAMEWORKS_PHASE},{RESOURCES_PHASE},); buildRules = (); dependencies = (); name = \"3105\"; productName = \"3105\"; productReference = {APP_REF}; productType = \"com.apple.product-type.application\"; }};")
    W("/* End PBXNativeTarget section */")
    W("")
    W("/* Begin PBXProject section */")
    W(f"\t\t{PROJECT_ID} = {{isa = PBXProject; attributes = {{LastSwiftUpdateCheck = 1540; LastUpgradeCheck = 1540; TargetAttributes = {{{NATIVE_TARGET} = {{CreatedOnToolsVersion = 15.4; }}; }}; }}; buildConfigurationList = {BCL_PROJECT}; compatibilityVersion = \"Xcode 14.0\"; developmentRegion = en; hasScannedForEncodings = 0; knownRegions = (en,Base,); mainGroup = {MAIN_GROUP}; productRefGroup = {PRODUCTS_GROUP}; projectDirPath = \"\"; projectRoot = \"\"; targets = ({NATIVE_TARGET},); }};")
    W("/* End PBXProject section */")
    W("")
    W("/* Begin PBXResourcesBuildPhase section */")
    res_files = ""
    for icon_name, bid in icon_bfs.items():
        res_files += f"\t\t\t{bid} /* {icon_name} in Resources */,\n"
    W(f"\t\t{RESOURCES_PHASE} = {{isa = PBXResourcesBuildPhase; buildActionMask = 2147483647; files = (\n{res_files}\t\t); runOnlyForDeploymentPostprocessing = 0; }};")
    W("/* End PBXResourcesBuildPhase section */")
    W("")
    W("/* Begin PBXSourcesBuildPhase section */")
    src_files = "".join(f"\t\t\t{bid} /* {os.path.basename(rel)} in Sources */,\n" for rel,bid in build_files.items() if not rel.endswith(".h"))
    W(f"\t\t{SOURCES_PHASE} = {{isa = PBXSourcesBuildPhase; buildActionMask = 2147483647; files = (\n{src_files}\t\t); runOnlyForDeploymentPostprocessing = 0; }};")
    W("/* End PBXSourcesBuildPhase section */")
    W("")

    def make_cfg(name, settings):
        cid = uid(f"CFG_{name}")
        body = "\n".join(f"\t\t\t\t{k} = {v};" for k,v in settings.items())
        return cid, f"\t\t{cid} = {{isa = XCBuildConfiguration; buildSettings = {{\n{body}\n\t\t\t}}; name = {name}; }};"

    bridging = os.path.join(ROOT, "Sources/ThreeOneOSFive-Bridging-Header.h")
    plist_path = os.path.join(ROOT, "Info.plist")
    common = {
        "CODE_SIGN_IDENTITY": '""',
        "CODE_SIGNING_REQUIRED": "NO",
        "CODE_SIGNING_ALLOWED": "NO",
        "ENABLE_HARDENED_RUNTIME": "NO",
        "IPHONEOS_DEPLOYMENT_TARGET": "16.0",
        "SDKROOT": "iphoneos",
        "SWIFT_VERSION": "5.0",
        "ONLY_ACTIVE_ARCH": "NO",
        "ARCHS": '"arm64"',
        "EXCLUDED_ARCHS": '"x86_64 i386"',
        "ALWAYS_SEARCH_USER_PATHS": "NO",
        "USE_HEADERMAP": "NO",
    }
    tgt = {**common,
        "INFOPLIST_FILE": f'"{plist_path}"',
        "OTHER_LDFLAGS": '"-Wl,-undefined,dynamic_lookup"',
        "PRODUCT_BUNDLE_IDENTIFIER": '"com.apple.mobile.MobileHouseArrest"',
        "PRODUCT_NAME": '"3105"',
        "PRODUCT_MODULE_NAME": '"App3105"',
        "SWIFT_OBJC_BRIDGING_HEADER": f'"{bridging}"',
        "TARGETED_DEVICE_FAMILY": '"1,2"',
    }

    pd_id, pd = make_cfg("Debug",      {**common, "SWIFT_OPTIMIZATION_LEVEL": '"-Onone"'})
    pr_id, pr = make_cfg("Release",    {**common, "SWIFT_OPTIMIZATION_LEVEL": '"-O"', "VALIDATE_PRODUCT": "YES"})
    td_id, td = make_cfg("TgtDebug",   {**tgt,    "SWIFT_OPTIMIZATION_LEVEL": '"-Onone"'})
    tr_id, tr = make_cfg("TgtRelease", {**tgt,    "SWIFT_OPTIMIZATION_LEVEL": '"-O"', "VALIDATE_PRODUCT": "YES"})

    W("/* Begin XCBuildConfiguration section */")
    W(pd); W(pr); W(td); W(tr)
    W("/* End XCBuildConfiguration section */")
    W("")
    W("/* Begin XCConfigurationList section */")
    W(f"\t\t{BCL_PROJECT} = {{isa = XCConfigurationList; buildConfigurations = ({pd_id},{pr_id},); defaultConfigurationIsVisible = 0; defaultConfigurationName = Release; }};")
    W(f"\t\t{BCL_TARGET}  = {{isa = XCConfigurationList; buildConfigurations = ({td_id},{tr_id},); defaultConfigurationIsVisible = 0; defaultConfigurationName = TgtRelease; }};")
    W("/* End XCConfigurationList section */")
    W("")
    W("\t};")
    W(f"\trootObject = {PROJECT_ID};")
    W("}")

    pbxproj = "\n".join(L)
    proj_dir = os.path.join(ROOT, "3105.xcodeproj")
    os.makedirs(proj_dir, exist_ok=True)
    with open(os.path.join(proj_dir, "project.pbxproj"), "w") as f:
        f.write(pbxproj)

    scheme_dir = os.path.join(proj_dir, "xcshareddata", "xcschemes")
    os.makedirs(scheme_dir, exist_ok=True)
    scheme = f'''<?xml version="1.0" encoding="UTF-8"?>
<Scheme LastUpgradeVersion="1540" version="1.7">
   <BuildAction parallelizeBuildables="YES" buildImplicitDependencies="YES">
      <BuildActionEntries>
         <BuildActionEntry buildForArchiving="YES" buildForRunning="YES" buildForTesting="YES" buildForProfiling="YES" buildForAnalyzing="YES">
            <BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{NATIVE_TARGET}" BuildableName="3105.app" BlueprintName="3105" ReferencedContainer="container:3105.xcodeproj"/>
         </BuildActionEntry>
      </BuildActionEntries>
   </BuildAction>
   <LaunchAction buildConfiguration="Release" selectedDebuggerIdentifier="" selectedLauncherIdentifier="Xcode.DebuggerFoundation.Launcher.LLDB" launchStyle="0" useCustomWorkingDirectory="NO" ignoresPersistentStateOnLaunch="NO" debugDocumentVersioning="YES" allowLocationSimulation="YES">
      <BuildableProductRunnable runnableDebuggingMode="0">
         <BuildableReference BuildableIdentifier="primary" BlueprintIdentifier="{NATIVE_TARGET}" BuildableName="3105.app" BlueprintName="3105" ReferencedContainer="container:3105.xcodeproj"/>
      </BuildableProductRunnable>
   </LaunchAction>
   <ArchiveAction buildConfiguration="Release" revealArchiveInOrganizer="YES"/>
</Scheme>'''
    with open(os.path.join(scheme_dir, "3105.xcscheme"), "w") as f:
        f.write(scheme)

    print(f"[setup] Generated 3105.xcodeproj: {len(swift_files)} sources, {len(ICONS)} icons")

if __name__ == "__main__":
    print("=== setup and build.py ===")
    write_files()
    gen_xcodeproj()
    print("=== Done ===")
